"""Controlled bilingual taxonomy; patterns are editable editorial heuristics."""

def category(key, en, zh, topics):
    return {'id': key, 'name': en, 'name_zh': zh,
            'topics': [dict(id=i, name=e, name_zh=z, pattern=p) for i, e, z, p in topics]}

